(()=>{if(window.__hsjUnifiedMonitoring20261023)return;window.__hsjUnifiedMonitoring20261023=true;
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','"':'&quot;'}[c]));
const kinds={avaliacao_enfermeiro:'enfermeiro',supervisao:'supervisao',monitoramento_administrativo:'administrativo'};
const names={enfermeiro:'Enfermeiro',supervisao:'Supervisão',administrativo:'Administrativo'};
const targets=['fila','pendencias','consulta_preop','exames','recebimento_nir','programacao','entrevista_tecnico','avaliacao_enfermeiro','mapa_cirurgico','pos_operatorio'];
let claims=[];
async function reload(){try{claims=await api('/rest/v1/monitoring_claims_hsj?select=*&order=created_at.desc&limit=5000')}catch(e){console.warn('Monitoramento novo',e);claims=[]}}
const oldLoad=window.load;window.load=async function(){const r=await oldLoad.apply(this,arguments);await reload();return r};
function renderClaims(){const type=kinds[S.view];if(!type)return;const c=document.getElementById('content');if(!c)return;const section=document.createElement('section');section.className='card';section.innerHTML='<div class="section-head"><div><h2>📥 Monitoramento — '+names[type]+'</h2><div class="sub">Somente demandas pendentes. As respondidas permanecem no histórico do cadastro.</div></div><button class="btn primary" onclick="hsjPullMonitor(\''+type+'\')">↩ Puxar monitoramento</button></div><div class="tablewrap"><table class="table"><thead><tr><th>Paciente</th><th>Motivo</th><th>Recebido</th><th>Ações</th></tr></thead><tbody>'+claims.filter(r=>r.monitor_type===type&&r.status==='aguardando').map(r=>{const x=S.rows.find(x=>x.id===r.surgery_id);return '<tr><td>'+safe(x?.patient_name||'Atendimento não localizado')+'</td><td>'+safe(r.reason)+'</td><td>'+safe(new Date(r.created_at).toLocaleString('pt-BR'))+'</td><td><button class="btn primary small" onclick="hsjRespondClaim(\''+r.id+'\')">Responder e encaminhar</button> <button class="btn small" onclick="hsjMonitorHistory(\''+r.surgery_id+'\')">Histórico</button></td></tr>'}).join('')+'</tbody></table></div>';c.prepend(section)}
window.hsjPullMonitor=function(type){const choices=S.rows.filter(x=>x.active&&x.stage!=='concluida');document.getElementById('modal').innerHTML='<div class="back"><div class="modal"><div class="mh"><b>↩ Puxar monitoramento — '+safe(names[type])+'</b><button class="btn" onclick="document.getElementById(\'modal\').innerHTML=\'\'">Fechar</button></div><div class="mb"><div class="field"><label>Buscar paciente por nome, CPF ou IDS</label><input id="hsjClaimSearch" placeholder="Digite para localizar" oninput="hsjSearchClaim()"></div><div id="hsjClaimMatches"></div><div class="field"><label>Motivo de puxar o monitoramento *</label><textarea id="hsjClaimReason" rows="3"></textarea></div><input type="hidden" id="hsjClaimId"></div><div class="mf"><button class="btn primary" onclick="hsjCreateClaim(\''+type+'\')">Registrar monitoramento</button></div></div></div>';window.hsjSearchClaim()};
window.hsjSearchClaim=function(){const q=document.getElementById('hsjClaimSearch')?.value.trim().toLocaleLowerCase('pt-BR')||'';const el=document.getElementById('hsjClaimMatches');if(!el)return;el.innerHTML=q.length<3?'<p class="sub">Informe ao menos 3 caracteres.</p>':S.rows.filter(x=>x.active&&[x.patient_name,x.cpf,x.ids].some(v=>String(v||'').toLocaleLowerCase('pt-BR').includes(q))).slice(0,20).map(x=>'<label class="check"><input type="radio" name="hsjClaimPatient" value="'+x.id+'" onchange="document.getElementById(\'hsjClaimId\').value=this.value"> '+safe(x.patient_name)+' — '+safe(x.ids||'')+' — '+safe(x.stage)+'</label>').join('')};
window.hsjCreateClaim=async function(type){const id=document.getElementById('hsjClaimId')?.value,reason=document.getElementById('hsjClaimReason')?.value.trim();if(!id||!reason)return alert('Selecione o paciente e informe o motivo.');try{await api('/rest/v1/monitoring_claims_hsj',{method:'POST',body:JSON.stringify({surgery_id:id,monitor_type:type,reason,created_by:uid})});document.getElementById('modal').innerHTML='';await load();renderCurrent()}catch(e){alert('Erro ao registrar monitoramento: '+e.message)}};
window.hsjRespondClaim=function(id){const r=claims.find(x=>x.id===id);if(!r)return;document.getElementById('modal').innerHTML='<div class="back"><div class="modal"><div class="mh"><b>Responder monitoramento</b><button class="btn" onclick="document.getElementById(\'modal\').innerHTML=\'\'">Fechar</button></div><div class="mb"><p><b>Motivo:</b> '+safe(r.reason)+'</p><div class="field"><label>Conduta / resposta *</label><textarea id="hsjClaimResponse" rows="5"></textarea></div><div class="field"><label>Etapa de destino *</label><select id="hsjClaimTarget">'+targets.map(t=>'<option value="'+t+'">'+safe(labels[t]||t)+'</option>').join('')+'</select></div></div><div class="mf"><button class="btn primary" onclick="hsjFinishClaim(\''+id+'\')">Responder e encaminhar</button></div></div></div>'};
window.hsjFinishClaim=async function(id){const response=document.getElementById('hsjClaimResponse')?.value.trim(),destination=document.getElementById('hsjClaimTarget')?.value;if(!response)return alert('Informe a conduta obrigatória.');try{await api('/rest/v1/rpc/hsj_responder_monitoramento_claim',{method:'POST',body:JSON.stringify({p_id:id,p_response:response,p_destination:destination})});document.getElementById('modal').innerHTML='';await load();renderCurrent()}catch(e){alert('Não foi possível encaminhar: '+e.message)}};
window.hsjMonitorHistory=async function(id){const x=S.rows.find(y=>y.id===id);const modal=document.getElementById('modal');modal.innerHTML='<div class="back"><div class="modal"><div class="mh"><b>Histórico de monitoramento — '+safe(x?.patient_name||'')+'</b><button class="btn" onclick="document.getElementById(\'modal\').innerHTML=\'\'">Fechar</button></div><div class="mb" id="hsjHistoryContent">Carregando...</div></div></div>';try{const [sup,adm,nur,own]=await Promise.all(['supervision_referrals','administrative_referrals','nurse_reviews','monitoring_claims_hsj'].map(t=>api('/rest/v1/'+t+'?surgery_id=eq.'+encodeURIComponent(id)+'&select=*')));const lines=[...sup.map(r=>({type:'Supervisão',date:r.resolved_at||r.created_at,reason:r.reason,response:r.resolution,status:r.status})),...adm.map(r=>({type:'Administrativo',date:r.resolved_at||r.created_at,reason:r.reason,response:r.resolution,status:r.status})),...nur.map(r=>({type:'Enfermeiro',date:r.reviewed_at,reason:r.reason,response:r.assessment,status:r.decision})),...own.map(r=>({type:names[r.monitor_type],date:r.resolved_at||r.created_at,reason:r.reason,response:r.response,status:r.status}))];lines.sort((a,b)=>new Date(b.date)-new Date(a.date));document.getElementById('hsjHistoryContent').innerHTML=lines.map(r=>'<div class="notice"><b>'+safe(r.type)+'</b> — '+safe(new Date(r.date).toLocaleString('pt-BR'))+'<p><b>Motivo:</b> '+safe(r.reason)+'</p><p><b>Resposta:</b> '+safe(r.response||'Pendente')+'</p><p><b>Situação:</b> '+safe(r.status)+'</p></div>').join('')||'Sem histórico de monitoramento.'}catch(e){document.getElementById('hsjHistoryContent').textContent='Falha ao consultar: '+e.message}};
function hideAnsweredLegacy(){if(!['supervisao','avaliacao_enfermeiro','monitoramento_administrativo'].includes(S.view))return;document.querySelectorAll('#content tbody tr').forEach(tr=>{const txt=tr.textContent||'';if(/✅\s*Respondido/i.test(txt)&&!tr.querySelector('button[onclick^="hsjRespondClaim"]'))tr.remove()});}
const oldRender=window.renderCurrent;window.renderCurrent=function(){const r=oldRender.apply(this,arguments);renderClaims();hideAnsweredLegacy();const c=document.getElementById('content');if(c&&S.view!=='indicadores'){c.querySelectorAll('button[onclick^="editPatient("],button[onclick^="hsjConsultarCadastroV24("]').forEach(b=>{const id=(b.getAttribute('onclick')||'').match(/'([0-9a-f-]{36})'/)?.[1];if(id&&!b.parentElement.querySelector('[data-hsj-hist]')){const btn=document.createElement('button');btn.className='btn small';btn.dataset.hsjHist='1';btn.textContent='📋 Histórico de monitoramento';btn.onclick=()=>hsjMonitorHistory(id);b.parentElement.append(btn)}})}return r};
})();